describe('Character Count Validation on Textarea', () => {
    beforeEach(() => {
        cy.visit('/your-form-page-url'); // Replace with your actual form page URL
    });

    it('should display the correct character count when typing within the limit', () => {
        const inputText = 'This is a test input that is under the character limit.';
        cy.get('textarea#your-textarea-id') // Replace with your actual textarea selector
            .type(inputText)
            .should('have.value', inputText);
        cy.get('#character-count') // Replace with your actual character count element selector
            .should('contain.text', inputText.length);
    });

    it('should not allow more than 500 characters and display the correct character count', () => {
        const inputText = 'A'.repeat(501); // 501 characters
        cy.get('textarea#your-textarea-id') // Replace with your actual textarea selector
            .type(inputText)
            .should('have.value', inputText.substring(0, 500)); // Ensure it only takes 500 characters
        cy.get('#character-count') // Replace with your actual character count element selector
            .should('contain.text', 500);
    });
});
